(async (sample) => {
  const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  await m.actions.ensureKernel();
  const notCentred = new Set(); const noIcon = new Set(); let inputs = 0; let buttons = 0;
  const scan = (where) => {
    for (const id of ['left-panel', 'right-panel']) {
      const host = document.getElementById(id); if (!host) continue;
      for (const el of host.querySelectorAll('input')) {
        if (['checkbox', 'radio', 'range', 'color', 'file'].includes(el.type) || el.offsetParent === null) continue;
        const numeric = el.type === 'number' || el.dataset.unit || el.dataset.pmField || el.dataset.num || /^\s*[-+]?\d+([.,]\d+)?\s*(mm|in|°|%)?\s*$/.test(el.value);
        if (!numeric) continue;
        inputs++;
        if (getComputedStyle(el).textAlign !== 'center') notCentred.add(`${where}:${el.dataset.pmField || el.dataset.num || el.name || el.className || el.type}`);
      }
      for (const b of host.querySelectorAll('button')) {
        if (b.offsetParent === null) continue;
        const text = b.textContent.trim();
        if (!text || text.length <= 1) continue; // ×, arrows: glyph buttons
        buttons++;
        const svg = b.querySelector('svg');
        if (!svg || svg.dataset.icon === 'dot') noIcon.add(`${where}:${b.dataset.pm || b.dataset.command || b.className}«${text.slice(0, 20)}»`);
      }
    }
  };
  if (m.state.editing) m.actions.cancelEditing({ quiet: true });
  await m.actions.closeProject({ force: true });
  await m.actions.openSampleAsk(sample); await sleep(1500);
  scan(sample);
  const skip = /^(open|save|export|import|print|exit|close|new|recent|clear|undo|redo|delete|rename|view:|style|show|theme|language|about|welcome|userGuide|tutorial|shortcuts|settings|startPage|leftPanel|rightPanel|bottomPanel|statusBar|fps|zoomFit|perspective|normalTo|gridPlane|section|macro|vault|checkIn|checkOut|camPost|plReport|inspExcel|inspCsv|inspReport|ilExport|markupReport|exportScad|harnessDrawing|shuffleBackground|backgroundImage|clearBackground|rebuild|suppress|unsuppress|rollback|editFeature|sketch$|sk:|exitSketch|cancelSketch|construction|largeAssembly|lights|measure|plRun|camGenerate|camSimulate|flowStudy|electronicsCooling|freeSurface|topologyStudy|dynamicStudy|dropTest|nonlinearStudy|renderView)/;
  for (const id of Object.keys(m.commands ?? {})) {
    if (skip.test(id)) continue;
    try {
      if (m.state.editing) m.actions.cancelEditing({ quiet: true });
      await Promise.race([m.run(id), sleep(1200)]); await sleep(120);
      scan(id);
    } catch { /* not available here */ }
  }
  if (m.state.editing) m.actions.cancelEditing({ quiet: true });
  return JSON.stringify({ inputs: inputs > 0, buttons: buttons > 0, nNotCentred: notCentred.size, nNoIcon: noIcon.size, notCentred: [...notCentred].slice(0, 40), noIcon: [...noIcon].slice(0, 40) });
})("basMountBracket")

